import{_ as t,C as o,o as i,c as p,a3 as l,E as r,w as h,j as s,a as e}from"./chunks/framework.CCylkYel.js";const y=JSON.parse('{"title":"Set up your agent","description":"","frontmatter":{},"headers":[],"relativePath":"ai/setup.md","filePath":"ai/setup.md"}'),d={name:"ai/setup.md"};function c(u,a,m,f,g,w){const n=o("ManualRelated");return i(),p("div",null,[a[1]||(a[1]=l('<h1 id="set-up-your-agent" tabindex="-1">Set up your agent <a class="header-anchor" href="#set-up-your-agent" aria-label="Permalink to &quot;Set up your agent&quot;">​</a></h1><p>Paste one block into your agent. It installs the s32 CLI, checks it, and saves the s32-cli skill with the rules to follow. You only paste: the words in the block are for the agent. Numbers match the panel: knob 01 is <code>1</code>, rack 1 is <code>1</code>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Close the <a href="https://editor.shik.tech" target="_blank" rel="noreferrer">web editor</a>. The S32 talks to one app at a time. That is all you do before you paste. If you do not have the s32 CLI yet, the block below installs it for you, or use the <a href="./../developers/getting-started">one-line install</a>. Update your S32 to the latest firmware first: <a href="./../settings/#update-firmware">Update the firmware</a>.</p><h2 id="starter-prompt" tabindex="-1">Paste this into your agent <a class="header-anchor" href="#starter-prompt" aria-label="Permalink to &quot;Paste this into your agent {#starter-prompt}&quot;">​</a></h2><p>The block works for every agent. Use the Copy button in its corner, then paste it at the start of a session. It holds the setup steps and the s32-cli skill. The agent asks before it installs anything.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set up the s32 CLI so you can work with my S32 MIDI controller. The s32 CLI talks to the S32 over USB. Do the steps in order and tell me how each one went.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. Install the s32 CLI. Show me the command and wait for my yes before you run it.</span></span>\n<span class="line"><span>   macOS or Linux: curl --proto &#39;=https&#39; --tlsv1.2 -fsSL https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.sh | sh</span></span>\n<span class="line"><span>   Windows (PowerShell): irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex</span></span>\n<span class="line"><span>   Never run sudo yourself. On Linux the installer may stop and name a command for the USB library, or print the commands that add the S32 USB rule. Both start with sudo. Show them to me and wait until I say I ran them. After the USB library, run the installer again.</span></span>\n<span class="line"><span>   If the s32 command is not found afterwards, open a new terminal, or add the folder the installer names to PATH.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>2. Check the s32 CLI: run `s32 --version`. It must be 2.1.0 or later. If it is older, run the install of step 1 again.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>3. Check it with the S32. I close the S32 web editor first: the S32 talks to one app at a time. Run `s32 --usb hello`. It works when it prints my S32&#39;s serial number and firmware version.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>4. If step 3 fails, run `s32 doctor` and show me what it prints. If it says no S32 was found, USB is not available or access was denied, while my S32 is plugged in and the web editor is closed, your sandbox may be blocking USB. Then stop, tell me so, and ask me for permission to run s32 outside your sandbox. Ask for s32 only, and change no other setting. Once I allow it, run `s32 doctor` again, then `s32 --usb hello`. If it still fails, do what its `next:` line says and tell me. Never check the connection with --loopback: the simulator always answers, and that says nothing about my S32.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>5. Save the skill: the lines after the line &quot;=== s32-cli skill (SKILL.md) ===&quot; are the text of the s32-cli skill, with the rules to follow. Leave that marker line itself out. If you support Agent Skills, save those lines as a new skill named s32-cli (they are the skill&#39;s SKILL.md). Otherwise save the same lines to the rules file you read at the start of every session: AGENTS.md, CLAUDE.md or your tool&#39;s own rules file. Tell me where you saved it.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>6. Check the setup: run `s32 --version` and `s32 --usb active`, then tell me the s32 CLI version, the name of the loaded project, and where you saved the skill. From now on, follow the skill. For anything it does not cover, read https://s32-manual.shik.tech/llms.txt.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>=== s32-cli skill (SKILL.md) ===</span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span>name: s32-cli</span></span>\n<span class="line"><span>description: Controls the S32 MIDI controller from the command line with the s32 CLI. Builds rack device chains, maps knobs, LFOs and envelopes to device parameters and MIDI, and reads and changes macros, racks, snapshots and projects safely (read, preview, ask, change, check). Use when the user mentions the S32 or the s32 CLI, or wants to change S32 racks, devices, knobs, macros, LFOs, snapshots or projects.</span></span>\n<span class="line"><span>---</span></span>\n<span class="line"><span># s32 CLI</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>The s32 CLI is the command-line tool for the S32 MIDI controller. It talks to the S32 over USB. Use it to read and change projects, racks and devices, knob macros, LFOs and snapshots.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Before you start</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- If the s32 CLI is not installed, ask me, then run the one-line install for my system from https://s32-manual.shik.tech/developers/getting-started. On Windows run it as `powershell -NoProfile -Command &#39;irm https://github.com/Shik-Tech/S32-CLI/releases/latest/download/install.ps1 | iex; exit $LASTEXITCODE&#39;` (single quotes, so your shell does not expand `$LASTEXITCODE` first), so a failed install returns a non-zero code.</span></span>\n<span class="line"><span>- Close the S32 web editor. The S32 talks to one app at a time.</span></span>\n<span class="line"><span>- Run `s32 --usb hello`. If it fails, run `s32 doctor`, show me what it prints and stop. If it says no S32 was found, USB is not available or access was denied while the S32 is plugged in, your sandbox may be blocking USB: ask me for permission to run s32 outside the sandbox, for s32 only. If `s32 doctor` is an unknown command, the s32 CLI is too old: ask me, then run the one-line install again.</span></span>\n<span class="line"><span>- From s32 2.1.0 on, every s32 command without `--loopback` talks to the S32 on USB and never switches to the simulator on its own. With an older s32 CLI (`s32 --version`), always pass `--usb` to commands for the S32. Use the simulator only when I ask to rehearse: add `--loopback`, for example `s32 --loopback hello`, and tell me you are using it. Its success says nothing about the S32. It starts fresh on every run, and its ids, names and ranges are not the S32&#39;s.</span></span>\n<span class="line"><span>- Once per session, after `s32 --usb hello` works, check the S32&#39;s firmware. Take the version from its `firmwareVersion` line and the latest published version from the `version` field of https://github.com/Shik-Tech/public-resources/raw/refs/heads/main/S32-Firmware/latest.json, or the version listed on https://shik.tech/support/manuals-firmware/. Compare them as three numbers, x.y.z: first x, then y, then z (1.1.10 is newer than 1.1.9). If the S32&#39;s version is older, tell me: &quot;A newer S32 firmware is available (&lt;latest&gt;); your S32 has &lt;S32 version&gt;. Update it on the panel: https://s32-manual.shik.tech/settings/#update-firmware&quot;. Only the panel updates the firmware: never update it yourself and never suggest an s32 command for it. If the versions are equal or the S32&#39;s is newer, say nothing about it. If you cannot fetch the version, or one of them is not three numbers, skip this check and say nothing about it.</span></span>\n<span class="line"><span>- Numbers match the panel: knob 01 is `1`, macro 1 is `1`, rack 1 is `1`, and a device&#39;s place in `device list` is its number (MIDI IN is `1`). Rack and device ids (`id=` in `rack list` and `device list`) are not places. Ids are different on every S32: read them with `s32 rack list` and `s32 device list 1` just before you use one, after your last change to that rack. Never copy an id from an example or from the simulator.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Ground rules</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- Every setting is `key=value`. Plain numbers and names only choose what you change. Numbers match the panel: knob 01 is 1, rack 1 is 1.</span></span>\n<span class="line"><span>- Read before you change, and read again after.</span></span>\n<span class="line"><span>- Before anything that asks first, back up the active project: run `s32 active`; if it shows `dirty=1`, tell me the backup misses unsaved changes and ask whether to save first with `s32 project save --wait`. Then run `s32 pull &lt;VOLUME&gt; &lt;UID&gt; s32-backup-&lt;UID&gt;-&lt;DATE_TIME&gt;.s32p` with its volume and uid and the current date and time. If s32 pull says the file already exists, choose a new name. Never pass --force.</span></span>\n<span class="line"><span>- Preview a change with `--dry-run` and show me the preview. Pass `--yes` only after I approved that exact change.</span></span>\n<span class="line"><span>- Stop on any exit code other than 0 and show me the error.</span></span>\n<span class="line"><span>- Never run a command that s32 commands --json marks &quot;service&quot;: true, and never pass --dev. If one seems needed, stop and tell me.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Workflow</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. Discover: `s32 --help` lists the commands, `s32 &lt;command&gt; --help` lists the keys of one command, `s32 commands --json` lists everything for a program.</span></span>\n<span class="line"><span>2. Read the current state: `rack list`, `device list`, `knobmap get`, `lfo cfg get`, `active`.</span></span>\n<span class="line"><span>3. Preview the change with `--dry-run` and show it to the person.</span></span>\n<span class="line"><span>4. Ask. Wait for a clear yes for that exact change.</span></span>\n<span class="line"><span>5. Change. A change prints what it did, then the new state.</span></span>\n<span class="line"><span>6. Read it back and compare with what was asked.</span></span>\n<span class="line"><span>7. Report: the commands you ran, what changed (old -&gt; new), and anything the S32 refused.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Device parameters</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `s32 schema --emit-schema-json` lists every device with each parameter&#39;s id, name and range.</span></span>\n<span class="line"><span>- Names work for `rate`, `gate` and `port`. Every other parameter is its number: `device param set 1 2 87=4`.</span></span>\n<span class="line"><span>- `device add` puts a new device before MIDI OUT. If the rack already has a Clock or a MIDI OUT, do not add another.</span></span>\n<span class="line"><span>- A new MIDI IN or MIDI OUT uses PORT USB. `port=1` is MIDI1, `port=2` is MIDI2 (MIDI OUT only: a MIDI IN stores it as MIDI1), `port=3` is USB HOST.</span></span>\n<span class="line"><span>- On SYNCED, times are steps of 24 per quarter note: 96 = 1/1, 48 = 1/2, 24 = 1/4, 12 = 1/8, 6 = 1/16.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Commands that ask first</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Each needs the person&#39;s approval and `--yes`. Preview it with `--dry-run` first.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- `project delete` removes a stored project.</span></span>\n<span class="line"><span>- `project load` replaces the live project.</span></span>\n<span class="line"><span>- `push --activate` sends a project and plays it.</span></span>\n<span class="line"><span>- `rack clear` removes every device in a rack.</span></span>\n<span class="line"><span>- `rack duplicate` copies a rack over another.</span></span>\n<span class="line"><span>- `snapshot delete` removes a snapshot.</span></span>\n<span class="line"><span>- `globals set` changes a global setting.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Exit codes</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```text</span></span>\n<span class="line"><span>0 ok · 1 local file/OS error · 2 usage · 3 link</span></span>\n<span class="line"><span>4 refused by the S32 · 5 not confirmed</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- 0: done. Read the new state.</span></span>\n<span class="line"><span>- 1: a file on this computer. Check the path.</span></span>\n<span class="line"><span>- 2: a typo or a missing value. Nothing was sent. Read the error and `s32 &lt;command&gt; --help`.</span></span>\n<span class="line"><span>- 3: the S32 could not be reached. The error says &quot;no S32 found on USB&quot;, &quot;USB is not available to this program&quot;, &quot;access denied&quot;, &quot;another program is using the S32&quot;, &quot;has no editor interface&quot;, &quot;could not open the S32&quot;, &quot;this build has no USB backend&quot;, &quot;timed out&quot;, &quot;HELLO failed&quot;, or that the s32 command-line tool or your S32&#39;s firmware &quot;is older&quot; or that they &quot;speak different editor protocols&quot;. Do what the error&#39;s `next:` line says; `s32 doctor` shows which step fails. If the error names the older side, a retry or another cable does not help.</span></span>\n<span class="line"><span>- 4: the S32 said no, or the target is not in its list. Read the error. Do not retry.</span></span>\n<span class="line"><span>  If the error says the S32 changed during the read, tell the user and run the command again when they are done. An add that says it was saved is saved: do not add it again.</span></span>\n<span class="line"><span>- 5: a command that asks first ran without `--yes`, or the answer was no. Nothing changed.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## What only the panel does</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- Formatting, compacting or migrating storage.</span></span>\n<span class="line"><span>- Firmware update. If an error says the S32&#39;s firmware is older, tell the user to update it on the panel: https://s32-manual.shik.tech/settings/#update-firmware. A retry does not help.</span></span>\n<span class="line"><span>- Pressing panel buttons and text entry.</span></span>\n<span class="line"><span>- Turning ARRANGE on: the CLI writes the song, the panel starts the playhead.</span></span>\n<span class="line"><span>- The CLI and the web editor never run at the same time.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Reference</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- https://s32-manual.shik.tech/llms.txt: an index of the AI and s32 CLI pages. Every page it links, except the manual home, is a Markdown copy.</span></span>\n<span class="line"><span>- https://s32-manual.shik.tech/ai/prompts: prompts with checked commands and read-backs.</span></span>\n<span class="line"><span>- `s32 &lt;command&gt; --help` and `s32 commands --json`: every command with its keys and values.</span></span></code></pre></div><p>To install the s32 CLI yourself, see <a href="./../developers/getting-started#manual-install">Manual install</a>.</p><h2 id="sandbox" tabindex="-1">If the agent cannot find the S32 <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;If the agent cannot find the S32 {#sandbox}&quot;">​</a></h2><p>Many agents run commands in a sandbox that can block USB. The s32 CLI then stops with <code>no S32 found on USB</code>, <code>USB is not available to this program</code> or <code>… (access denied)</code>, although the S32 is plugged in and the web editor is closed. <code>s32 doctor</code> shows which step fails. The prompt tells the agent to stop and ask you. Allow the s32 CLI to run outside the sandbox, and only the s32 CLI:</p><ul><li><strong>Codex:</strong> approve the request when the agent asks to run the s32 CLI outside the sandbox, with the narrowest scope it offers (<a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">Codex sandboxing</a>).</li><li><strong>Claude Code:</strong> with the sandbox on, approve the retry outside the sandbox. To allow it every time, add <code>&quot;excludedCommands&quot;: [&quot;s32 *&quot;]</code> under <code>sandbox</code> in your settings. That is a standing exemption for every matching s32 CLI call, and it is your choice. A call that starts with <code>cd</code>, writes to a file or uses <code>$(...)</code> still runs in the sandbox (<a href="https://code.claude.com/docs/en/sandboxing" target="_blank" rel="noreferrer">Claude Code sandboxing</a>).</li><li><strong>Other agents:</strong> approve running the s32 CLI outside the sandbox, or add it to the commands the agent may run outside it.</li></ul><p>If <code>s32 doctor</code> says another program is using the S32, close the web editor and any other s32 CLI session.</p><h2 id="rehearse-without-the-s32" tabindex="-1">Rehearse without the S32 <a class="header-anchor" href="#rehearse-without-the-s32" aria-label="Permalink to &quot;Rehearse without the S32&quot;">​</a></h2><p>To rehearse without hardware, ask the agent to use the simulator (<code>--loopback</code>); it tells you when it does. The simulator starts fresh on every run. Its ids, names and ranges are not your S32&#39;s, and a command that works there says nothing about your S32.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span></span></code></pre></div>',15)),r(n,null,{default:h(()=>[...a[0]||(a[0]=[s("ul",null,[s("li",null,[s("a",{href:"./"},"Overview"),e(" — What an agent can do with your S32, in three steps")]),s("li",null,[s("a",{href:"./prompts"},"Prompts and examples"),e(" — Quick starters and prompts for racks, modulation and knob mappings, with checked commands")]),s("li",null,[s("a",{href:"./safe-changes"},"Change safely"),e(" — Read, preview, ask, change, check")]),s("li",null,[s("a",{href:"./for-agents"},"For agents"),e(" — What agents read: llms.txt, Markdown copies, finding commands")])],-1)])]),_:1})])}const b=t(d,[["render",c]]);export{y as __pageData,b as default};
